package com.hari.tracea.urlconnection

import com.hari.tracea.core.config.TraceaConfig
import com.hari.tracea.core.pipeline.NetworkEventCollector
import java.net.HttpURLConnection
import java.net.URLConnection
import javax.net.ssl.HttpsURLConnection

/**
 * Static bridge called by ASM-injected bytecode whenever [java.net.URL.openConnection]
 * is invoked anywhere in the app or third-party SDKs (such as Adobe, Google, etc.).
 *
 * **WARNING: This class is referenced by generated bytecode.**
 * The class name, package, and [wrap] method signature MUST NOT change
 * without also updating the ASM MethodVisitor in tracea-gradle-plugin.
 */
object TraceaUrlConnectionTracker {

    @Volatile
    private var collector: NetworkEventCollector? = null

    @Volatile
    private var config: TraceaConfig? = null

    /**
     * Called by [com.hari.tracea.Tracea.initialize] to install the collector & config.
     */
    @JvmStatic
    fun install(collector: NetworkEventCollector, config: TraceaConfig) {
        this.collector = collector
        this.config = config
    }

    /**
     * Called by ASM-injected bytecode directly after [java.net.URL.openConnection].
     *
     * @param connection the raw URLConnection returned by URL.openConnection()
     * @return a wrapped [TraceaHttpsURLConnection], [TraceaHttpURLConnection], or the original connection
     */
    @JvmStatic
    fun wrap(connection: URLConnection): URLConnection {
        val currentCollector = collector ?: return connection
        val currentConfig = config ?: return connection
        if (!currentConfig.enabled) return connection

        // Avoid double wrapping
        if (connection is TraceaHttpURLConnection || connection is TraceaHttpsURLConnection) {
            return connection
        }

        return when (connection) {
            is HttpsURLConnection -> TraceaHttpsURLConnection(connection, currentCollector, currentConfig)
            is HttpURLConnection -> TraceaHttpURLConnection(connection, currentCollector, currentConfig)
            else -> connection
        }
    }

    @JvmStatic
    fun reset() {
        collector = null
        config = null
    }
}
